//! Leyline Studio desktop application (`docs/roadmap.md` phase 5).
//!
//! First slice: the library browser. Studio opens a library through the
//! SDK — never the catalog directly — renders the photo grid with cached
//! thumbnails, and shows the metadata of the selected photo.

mod format;

/// UI generated by `slint-build` from `ui/studio.slint`.
#[allow(missing_docs, clippy::all)]
mod ui {
    slint::include_modules!();
}

use std::path::Path;
use std::rc::Rc;

use leyline_sdk::{ColorLabel, GridQuery, Library, PreviewKind};
use slint::{ComponentHandle, ModelRc, SharedString, VecModel};

use ui::{Cell, StudioWindow};

/// Preformatted details of one grid cell, ready for the side panel.
struct Details {
    filename: String,
    path: String,
    capture: String,
    dimensions: String,
    file_size: String,
    camera: String,
    lens: String,
    exposure: String,
}

fn main() -> std::process::ExitCode {
    match run() {
        Ok(()) => std::process::ExitCode::SUCCESS,
        Err(message) => {
            eprintln!("error: {message}");
            std::process::ExitCode::FAILURE
        }
    }
}

fn run() -> Result<(), String> {
    let Some(root) = std::env::args().nth(1) else {
        return Err("usage: leyline-studio <library-dir>".to_owned());
    };
    let mut library = Library::open(Path::new(&root)).map_err(|e| e.to_string())?;

    let info = library.catalog().library().map_err(|e| e.to_string())?;
    let query = GridQuery::default();
    let total = library.catalog().count(&query).map_err(|e| e.to_string())?;
    let items = library.catalog().grid(&query).map_err(|e| e.to_string())?;

    let mut cells = Vec::with_capacity(items.len());
    let mut details = Vec::with_capacity(items.len());
    for item in &items {
        // A missing or unrenderable preview leaves the cell empty rather
        // than failing the whole browser.
        let thumbnail = library
            .preview(item.asset_id, PreviewKind::Thumbnail)
            .ok()
            .and_then(|file| slint::Image::load_from_path(&file.path).ok())
            .unwrap_or_default();
        cells.push(Cell {
            thumbnail,
            filename: SharedString::from(item.filename.as_str()),
            stars: SharedString::from(format::stars(item.rating)),
            label: label_color(item.color_label),
            has_label: item.color_label.is_some(),
        });
        details.push(cell_details(&library, item.asset_id)?);
    }

    let window = StudioWindow::new().map_err(|e| e.to_string())?;
    window.set_library_name(SharedString::from(info.name.as_str()));
    window.set_status_line(SharedString::from(status_line(items.len(), total)));
    window.set_cells(ModelRc::from(Rc::new(VecModel::from(cells))));

    let handle = window.as_weak();
    window.on_select(move |index| {
        let Some(window) = handle.upgrade() else {
            return;
        };
        let Some(detail) = usize::try_from(index).ok().and_then(|i| details.get(i)) else {
            return;
        };
        window.set_detail_filename(SharedString::from(detail.filename.as_str()));
        window.set_detail_path(SharedString::from(detail.path.as_str()));
        window.set_detail_capture(SharedString::from(detail.capture.as_str()));
        window.set_detail_dimensions(SharedString::from(detail.dimensions.as_str()));
        window.set_detail_file_size(SharedString::from(detail.file_size.as_str()));
        window.set_detail_camera(SharedString::from(detail.camera.as_str()));
        window.set_detail_lens(SharedString::from(detail.lens.as_str()));
        window.set_detail_exposure(SharedString::from(detail.exposure.as_str()));
    });

    window.run().map_err(|e| e.to_string())
}

/// Reads and formats everything the side panel shows for one asset.
fn cell_details(library: &Library, asset: leyline_sdk::AssetId) -> Result<Details, String> {
    let d = library
        .catalog()
        .asset_details(asset)
        .map_err(|e| e.to_string())?;
    let meta = d.metadata.as_ref();
    Ok(Details {
        filename: d.filename,
        path: d.relative_path,
        capture: d
            .capture_date
            .map_or_else(|| "—".to_owned(), format::capture_date),
        dimensions: format::dimensions(d.width, d.height),
        file_size: format::file_size(d.file_size),
        camera: meta.and_then(|m| m.camera.as_ref()).map_or_else(
            || "—".to_owned(),
            |c| format!("{} {}", c.manufacturer, c.model),
        ),
        lens: meta.and_then(|m| m.lens.as_ref()).map_or_else(
            || "—".to_owned(),
            |l| format!("{} {}", l.manufacturer, l.model),
        ),
        exposure: meta.map_or_else(String::new, format::exposure_line),
    })
}

/// The header line above the grid.
fn status_line(shown: usize, total: u64) -> String {
    if shown as u64 >= total {
        format!("{total} photos")
    } else {
        format!("{shown} of {total} photos")
    }
}

/// The dot color of a catalog color label.
fn label_color(label: Option<ColorLabel>) -> slint::Color {
    match label {
        Some(ColorLabel::Red) => slint::Color::from_rgb_u8(0xE0, 0x4F, 0x4F),
        Some(ColorLabel::Yellow) => slint::Color::from_rgb_u8(0xE0, 0xC0, 0x4F),
        Some(ColorLabel::Green) => slint::Color::from_rgb_u8(0x6F, 0xBF, 0x6F),
        Some(ColorLabel::Blue) => slint::Color::from_rgb_u8(0x5F, 0x8F, 0xDF),
        Some(ColorLabel::Purple) => slint::Color::from_rgb_u8(0xA0, 0x6F, 0xDF),
        None => slint::Color::default(),
    }
}
